<script>
const createModal=document.getElementById('createModal');
document.getElementById('newPost')?.addEventListener('click',()=>createModal.classList.add('open'));
document.querySelectorAll('.day-add').forEach(button=>button.addEventListener('click',()=>{const form=createModal.querySelector('form');form.elements.publish_date.value=button.dataset.date;createModal.classList.add('open')}));
document.querySelectorAll('[data-open-modal]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.openModal).classList.add('open')));
document.querySelectorAll('[data-close-modal]').forEach(button=>button.addEventListener('click',()=>button.closest('.modal-bg').classList.remove('open')));
document.querySelectorAll('.modal-bg').forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)modal.classList.remove('open')}));
document.getElementById('copyPublicLink')?.addEventListener('click',async event=>{const link=document.getElementById('publicLinkValue');try{await navigator.clipboard.writeText(link.value)}catch{link.select();document.execCommand('copy')}event.currentTarget.textContent='Tautan disalin'});
const editor=document.getElementById('infoEditor'),links=document.getElementById('infoLinkPreview');
function previewLinks(){if(!editor||!links)return;links.replaceChildren();const seen=new Set();for(const match of (editor.value.match(/(?:https?:\/\/|www\.)[^\s<>'"]+/gi)||[])){const raw=match.replace(/[.,;:!?)}\]]+$/,'');const href=/^https?:\/\//i.test(raw)?raw:'https://'+raw;if(seen.has(href))continue;seen.add(href);const a=document.createElement('a');a.href=href;a.target='_blank';a.rel='noopener noreferrer';a.textContent='↗ '+raw;links.append(a)}}
editor?.addEventListener('input',previewLinks);previewLinks();
document.getElementById('hideGuide')?.addEventListener('click',()=>document.getElementById('quickGuide').remove());
if(new URLSearchParams(location.search).get('view')==='week'){const calendar=document.querySelector('.month-grid');if(calendar){calendar.classList.add('week-mode');calendar.querySelectorAll('.day[data-week]').forEach(day=>day.hidden=day.dataset.week!==calendar.dataset.week);}}
</script>
@else
<div class="empty panel"><h2>Belum ada planner klien yang ditugaskan</h2><p>Minta Project Manager menambahkan Anda ke tim planner klien.</p>@if(auth()->user()->role==='pm')<a class="btn primary" href="{{ route('clients.create') }}">Tambah klien</a>@endif</div>
